function icon(name, size) {
    let svg = ICONS[name] || '';
    if (size && svg) {
        svg = svg.replace(/width="18"/g, `width="${size}"`).replace(/height="18"/g, `height="${size}"`);
    }
    return svg;
}

// --- i18n engine ---

function getLang() {
    return localStorage.getItem('jt-glogarch-lang') || 'en';
}

function setLang(lang) {
    localStorage.setItem('jt-glogarch-lang', lang);
    applyI18n();
    document.dispatchEvent(new CustomEvent('langchange', {detail: {lang}}));
}

function t(key) {
    const lang = getLang();
    return (I18N[lang] && I18N[lang][key]) || (I18N.en[key]) || key;
}

// --- Backend messages ---------------------------------------------------------
// Job notes, refusals and errors arrive in English: a job row is written once
// and read in every UI language. Each `srv_*` key holds the exact English
// sentence the backend writes, with {a}..{l} for a value and {m} for a nested
// message (translated in turn). trSrv() translates text made of these — also
// several joined with ". ", "; " or " | " — and leaves anything else as it was.
// Only ever call it on text the server wrote, never on log content: a log line
// may contain one of these sentences too.
let _srvRules = null;
const _srvCache = new Map();

function _srvCompile() {
    const rules = [];
    for (const key of Object.keys(I18N.en)) {
        if (!key.startsWith('srv_')) continue;
        const parts = I18N.en[key].split(/\{([a-z])\}/);
        const seen = new Set();
        const lits = [];
        let src = '^';
        for (let i = 0; i < parts.length; i++) {
            if (i % 2 === 0) {
                src += parts[i].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                if (parts[i].trim()) lits.push(parts[i]);
                continue;
            }
            const name = parts[i];
            if (seen.has(name)) { src += '\\k<' + name + '>'; continue; }
            seen.add(name);
            const first = i === 1 && parts[0] === '';
            const last = i === parts.length - 2 && parts[parts.length - 1] === '';
            // A value never spans a sentence break or a " | " list; a message may.
            const cls = name === 'm' ? '[\\s\\S]+' : (first ? '\\S+' : '(?:(?!\\. )[^|])+');
            src += '(?<' + name + '>' + cls + (last ? '' : '?') + ')';
        }
        rules.push({key, re: new RegExp(src + '$'), lits,
                    weight: lits.reduce((n, l) => n + l.length, 0)});
    }
    return rules.sort((a, b) => b.weight - a.weight);
}

function _srvMatch(seg, table) {
    if (!_srvRules) _srvRules = _srvCompile();
    for (const r of _srvRules) {
        if (!r.lits.every(l => seg.indexOf(l) !== -1)) continue;
        const m = r.re.exec(seg);
        if (!m) continue;
        const tr = table[r.key];
        if (!tr) return null;
        return tr.replace(/\{([a-z])\}/g, (_, n) => {
            const v = (m.groups && m.groups[n]) || '';
            return n === 'm' ? trSrv(v) : v;
        });
    }
    return null;
}

function _srvSegments(s, table) {
    const parts = s.split(/(\. |; | \| )/);
    if (parts.length === 1) return s;
    let out = '';
    let sep = '';
    let i = 0;
    while (i < parts.length) {
        let hit = null, next = i + 2, ateDot = false;
        for (let j = parts.length - 1; j >= i; j -= 2) {   // longest run first
            const seg = parts.slice(i, j + 1).join('');
            let h = _srvMatch(seg, table), dot = false;
            if (h == null && parts[j + 1] === '. ') { h = _srvMatch(seg + '.', table); dot = h != null; }
            if (h != null) { hit = h; next = j + 2; ateDot = dot; break; }
        }
        const piece = hit != null ? hit : parts[i];
        if (!out) out = piece;
        else if (hit == null) out += sep + piece;
        else if (sep === '; ') out += '；' + piece;
        else if (sep === ' | ') out += ' | ' + piece;
        else out += (/[。！？]$/.test(out) ? '' : '。') + piece;
        sep = parts[next - 1] || '';
        if (ateDot && sep === '. ') sep = ' ';
        i = next;
    }
    return out;
}

function trSrv(text) {
    if (text == null) return '';
    const s = String(text);
    const code = getLang();
    const table = I18N[code];
    if (!s || code === 'en' || !table) return s;
    const ck = code + '\u0000' + s;
    if (_srvCache.has(ck)) return _srvCache.get(ck);
    let out = _srvMatch(s, table);
    if (out == null) out = _srvSegments(s, table);
    // A sentence break inside Chinese/Japanese text takes no space.
    out = out.replace(/([。！？]) (?=\S)/g, '$1');
    if (_srvCache.size > 3000) _srvCache.clear();
    _srvCache.set(ck, out);
    return out;
}

function applyI18n() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        const iconName = el.getAttribute('data-icon');
        const prefix = iconName ? icon(iconName) + ' ' : '';
        el.innerHTML = prefix + t(key);
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        el.placeholder = t(el.getAttribute('data-i18n-placeholder'));
    });
    document.querySelectorAll('[data-i18n-opt]').forEach(el => {
        el.textContent = t(el.getAttribute('data-i18n-opt'));
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        el.title = t(el.getAttribute('data-i18n-title'));
    });
    const switcher = document.getElementById('lang-select');
    if (switcher) switcher.value = getLang();
    document.documentElement.lang = I18N[getLang()] ? getLang() : 'en';
}

// --- Theme engine ---

function getTheme() {
    return localStorage.getItem('jt-glogarch-theme') || 'light';
}

function setTheme(theme) {
    localStorage.setItem('jt-glogarch-theme', theme);
    applyTheme();
}

function toggleTheme() {
    setTheme(getTheme() === 'dark' ? 'light' : 'dark');
}

function applyTheme() {
    document.documentElement.setAttribute('data-theme', getTheme());
    const btn = document.getElementById('theme-toggle');
    if (btn) {
        const isDark = getTheme() === 'dark';
        btn.innerHTML = isDark ? icon('sun') : icon('moon');
        btn.title = isDark ? t('theme_light') : t('theme_dark');
    }
}

document.addEventListener('DOMContentLoaded', () => {
    applyTheme();
    applyI18n();
});

// ---- The app's own dropdown, used instead of the browser's -----------------

function _skinPaint(sel, trigger, optionsDiv, wrapper) {
    const chosen = sel.options[sel.selectedIndex];
    trigger.querySelector('span').textContent = chosen ? chosen.text : '';
    optionsDiv.textContent = '';
    Array.from(sel.options).forEach((opt, i) => {
        const d = document.createElement('div');
        d.className = 'custom-select-option' + (i === sel.selectedIndex ? ' selected' : '');
        d.textContent = opt.text;
        d.setAttribute('data-value', opt.value);
        d.addEventListener('click', () => {
            sel.value = opt.value;
            // MUST bubble: data-act-change handlers are delegated on `document`.
            sel.dispatchEvent(new Event('change', { bubbles: true }));
            wrapper.classList.remove('open');
        });
        optionsDiv.appendChild(d);
    });
}

/** Code sets select.value directly and refills options; the skin has to follow both, or it
 *  shows something other than what the hidden select will submit. */
function _skinFollow(sel) {
    if (sel._skinFollowed) return;
    sel._skinFollowed = true;
    ['value', 'selectedIndex'].forEach(prop => {
        const native = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, prop);
        Object.defineProperty(sel, prop, {
            configurable: true,
            get: function () { return native.get.call(this); },
            set: function (v) { native.set.call(this, v); if (this._skinRepaint) this._skinRepaint(); },
        });
    });
    new MutationObserver(() => { if (sel._skinRepaint) sel._skinRepaint(); })
        .observe(sel, { childList: true, subtree: true, characterData: true });
}

function initCustomSelects() {
    document.querySelectorAll('select:not(.no-custom)').forEach(sel => {
        const old = sel.closest('.custom-select');
        if (old) {
            old.parentNode.insertBefore(sel, old);
            old.remove();
        }
        sel.classList.add('custom-done');
        sel.style.display = 'none';

        const wrapper = document.createElement('div');
        wrapper.className = 'custom-select';
        if (sel.id) wrapper.dataset.for = sel.id;
        const trigger = document.createElement('div');
        trigger.className = 'custom-select-trigger';
        trigger.innerHTML = '<span></span><span class="arrow">&#9662;</span>';
        const optionsDiv = document.createElement('div');
        optionsDiv.className = 'custom-select-options';

        sel._skinRepaint = () => _skinPaint(sel, trigger, optionsDiv, wrapper);
        sel._skinRepaint();
        _skinFollow(sel);

        trigger.addEventListener('click', (e) => {
            e.stopPropagation();
            document.querySelectorAll('.custom-select.open').forEach(cs => { if (cs !== wrapper) cs.classList.remove('open'); });
            optionsDiv.classList.toggle('drop-down', window.innerHeight - trigger.getBoundingClientRect().bottom > 220);
            wrapper.classList.toggle('open');
        });

        sel.parentNode.insertBefore(wrapper, sel);
        wrapper.appendChild(trigger);
        wrapper.appendChild(optionsDiv);
        wrapper.appendChild(sel);
    });
}

document.addEventListener('click', () => {
    document.querySelectorAll('.custom-select.open').forEach(cs => cs.classList.remove('open'));
});

// A select rendered later (a dialog, a form) gets the skin without each caller remembering.
document.addEventListener('DOMContentLoaded', () => {
    let pending = false;
    new MutationObserver(() => {
        if (pending) return;
        pending = true;
        setTimeout(() => {
            pending = false;
            if (document.querySelector('select:not(.no-custom):not(.custom-done)')) initCustomSelects();
        }, 30);
    }).observe(document.body, { childList: true, subtree: true });
});
